29	// cliEscKey renders an ASCII name entirely as JSON \u00XX escapes, so the
30	// fixture JSON literally uses escaped key spellings.
31	func cliEscKey(name string) string {
32		var b strings.Builder
33		for _, r := range name {
34			fmt.Fprintf(&b, `\u%04x`, r)
35		}
36		return b.String()
37	}
