39	// readFileSnapshot returns a file's bytes so a later assertion can prove the
40	// supposedly read-only input was not rewritten.
41	func readFileSnapshot(t *testing.T, path string) []byte {
42		t.Helper()
43		data, err := os.ReadFile(path)
44		if err != nil {
45			t.Fatal(err)
46		}
47		return data
48	}
