1	package batchreg
2	
3	import (
4		"errors"
5		"strings"
6		"testing"
7	)
8	
9	// When a batch id is introduced by the manifest itself, a later conflicting
10	// record must be reported against the id's first manifest occurrence — never
11	// against an intermediate identical record. Duplicate confirmations in
12	// between neither become the new source nor replace the first record's
13	// content, no matter how often the identical record is repeated.
14	func TestImportConflictSourceIsFirstManifestOccurrence(t *testing.T) {
15		cases := []struct {
16			name       string
17			inputs     []Input
18			wantPos    int
19			wantFields []string
20		}{
21			{
22				name: "one intermediate duplicate, quantity differs",
23				inputs: []Input{
24					{Batch: "B1", Product: "P-7", Quantity: 10, Unit: "kg"}, // first occurrence
25					{Batch: "B2", Product: "P-8", Quantity: 1, Unit: "box"},
26					{Batch: "B1", Product: "P-7", Quantity: 10, Unit: "kg"}, // identical repeat
27					{Batch: "B1", Product: "P-7", Quantity: 11, Unit: "kg"}, // conflict
28				},
29				wantPos:    4,
30				wantFields: []string{"quantity"},
31			},
32			{
33				name: "several intermediate duplicates, product differs",
34				inputs: []Input{
35					{Batch: "B1", Product: "P-7", Quantity: 10, Unit: "kg"},
36					{Batch: "B1", Product: "P-7", Quantity: 10, Unit: "kg"},
37					{Batch: "B1", Product: "P-7", Quantity: 10, Unit: "kg"},
38					{Batch: "B1", Product: "P-9", Quantity: 10, Unit: "kg"},
39				},
40				wantPos:    4,
41				wantFields: []string{"product"},
42			},
43			{
44				name: "unit differs after a duplicate",
45				inputs: []Input{
46					{Batch: "B1", Product: "P-7", Quantity: 10, Unit: "kg"},
47					{Batch: "B1", Product: "P-7", Quantity: 10, Unit: "kg"},
48					{Batch: "B1", Product: "P-7", Quantity: 10, Unit: "g"},
49				},
50				wantPos:    3,
51				wantFields: []string{"unit"},
52			},
53			{
54				name: "all three fields differ after duplicates",
55				inputs: []Input{
56					{Batch: "B1", Product: "P-7", Quantity: 10, Unit: "kg"},
57					{Batch: "B1", Product: "P-7", Quantity: 10, Unit: "kg"},
58					{Batch: "B1", Product: "P-9", Quantity: 11, Unit: "g"},
59				},
60				wantPos:    3,
61				wantFields: []string{"product", "quantity", "unit"},
62			},
63		}
64		for _, tc := range cases {
65			t.Run(tc.name, func(t *testing.T) {
66				reg := &Registry{Version: FormatVersion}
67				results, err := Import(reg, tc.inputs)
68				var ce *ManifestConflictError
69				if !errors.As(err, &ce) {
70					t.Fatalf("got %v, want ManifestConflictError", err)
71				}
72				if ce.Position != tc.wantPos || ce.Batch != "B1" {
73					t.Errorf("conflict = record %d batch %q, want record %d batch B1", ce.Position, ce.Batch, tc.wantPos)
74				}
75				if ce.Source != "manifest" || ce.PrevPos != 1 {
76					t.Errorf("source = %q prev %d, want manifest record 1 (the first occurrence, not an intermediate duplicate)", ce.Source, ce.PrevPos)
77				}
78				if strings.Join(ce.Fields, ",") != strings.Join(tc.wantFields, ",") {
79					t.Errorf("fields = %v, want %v", ce.Fields, tc.wantFields)
80				}
81				msg := err.Error()
82				if !strings.Contains(msg, "conflicts with manifest record 1") {
83					t.Errorf("error must name manifest record 1 as the conflict source: %v", msg)
84				}
85				if strings.Contains(msg, "conflicts with manifest record 2") || strings.Contains(msg, "conflicts with manifest record 3") {
86					t.Errorf("an intermediate duplicate must not become the conflict source: %v", msg)
87				}
88				if results != nil {
89					t.Errorf("rejected import must report no results, got %+v", results)
90				}
91				if len(reg.Batches) != 0 {
92					t.Errorf("rejected import left new batches in the registry: %+v", reg.Batches)
93				}
94			})
95		}
96	}
97	
98	// When the batch id was already registered before the import, identical
99	// manifest records only confirm the stored record — however often they
100	// repeat. A later differing record conflicts with the registered record, and
101	// the error must say so; the confirmations must not turn the source into a
102	// manifest record.
103	func TestImportConflictSourceStaysRegistryAfterConfirmations(t *testing.T) {
104		stored := Batch{Batch: "B1", Product: "P-7", Quantity: 10, Unit: "kg"}
105		reg := &Registry{Version: FormatVersion, Batches: []Batch{stored}}
106		inputs := []Input{
107			{Batch: "B1", Product: "P-7", Quantity: 10, Unit: "kg"}, // confirms the stored record
108			{Batch: "B2", Product: "P-8", Quantity: 1, Unit: "box"},
109			{Batch: "B1", Product: "P-7", Quantity: 10, Unit: "kg"}, // confirms again
110			{Batch: "B1", Product: "P-7", Quantity: 10, Unit: "kg"}, // and again
111			{Batch: "B1", Product: "P-7", Quantity: 12, Unit: "kg"}, // conflict
112		}
113		results, err := Import(reg, inputs)
114		var ce *ManifestConflictError
115		if !errors.As(err, &ce) {
116			t.Fatalf("got %v, want ManifestConflictError", err)
117		}
118		if ce.Position != 5 || ce.Batch != "B1" {
119			t.Errorf("conflict = record %d batch %q, want record 5 batch B1", ce.Position, ce.Batch)
120		}
121		if ce.Source != "registry" {
122			t.Errorf("source = %q, want %q: the conflict is with the registered record", ce.Source, "registry")
123		}
124		if ce.PrevPos != 0 {
125			t.Errorf("PrevPos = %d, want 0: no manifest record is the source", ce.PrevPos)
126		}
127		if strings.Join(ce.Fields, ",") != "quantity" {
128			t.Errorf("fields = %v, want [quantity]", ce.Fields)
129		}
130		msg := err.Error()
131		if !strings.Contains(msg, "conflicts with the registered record") {
132			t.Errorf("error must name the registered record as the conflict source: %v", msg)
133		}
134		if strings.Contains(msg, "conflicts with manifest record") {
135			t.Errorf("a duplicate confirmation must not become the conflict source: %v", msg)
136		}
137		if results != nil {
138			t.Errorf("rejected import must report no results, got %+v", results)
139		}
140		if len(reg.Batches) != 1 || reg.Batches[0] != stored {
141			t.Errorf("rejected import mutated the registry: %+v", reg.Batches)
142		}
143	}
144	
145	// Manifest text is compared after trimming leading and trailing whitespace,
146	// so padded spellings of one id share a single source: the conflict is
147	// reported against the id's first (padded) occurrence. Ids whose interior
148	// characters or casing differ remain different batches and never conflict.
149	func TestImportConflictSourceWithTrimmedIDs(t *testing.T) {
150		manifest := []byte(`[
151			{"batch": " B1 ", "product": "P-7", "quantity": 10, "unit": "kg"},
152			{"batch": "B 1", "product": "P-8", "quantity": 1, "unit": "box"},
153			{"batch": "b1", "product": "P-9", "quantity": 2, "unit": "g"},
154			{"batch": "B1", "product": "P-7", "quantity": 10, "unit": "kg"},
155			{"batch": "\tB1\n", "product": "P-7", "quantity": 11, "unit": "kg"}
156		]`)
157		inputs, err := ParseManifest(manifest)
158		if err != nil {
159			t.Fatal(err)
160		}
161		reg := &Registry{Version: FormatVersion}
162		_, err = Import(reg, inputs)
163		var ce *ManifestConflictError
164		if !errors.As(err, &ce) {
165			t.Fatalf("got %v, want ManifestConflictError", err)
166		}
167		if ce.Position != 5 || ce.Batch != "B1" {
168			t.Errorf("conflict = record %d batch %q, want record 5 batch B1", ce.Position, ce.Batch)
169		}
170		if ce.Source != "manifest" || ce.PrevPos != 1 {
171			t.Errorf("source = %q prev %d, want manifest record 1: trimming must not move the source", ce.Source, ce.PrevPos)
172		}
173		if strings.Join(ce.Fields, ",") != "quantity" {
174			t.Errorf("fields = %v, want [quantity]", ce.Fields)
