// runImportChild re-executes the test binary in wrapped one-command mode with
// the chosen fault and returns the child's exit code plus captured output.
func runImportChild(t *testing.T, registry, manifest string, fault saveFault, reason string) (code int, stdout, stderr []byte) {
	t.Helper()
	exe, err := os.Executable()
	if err != nil {
		t.Fatal(err)
	}
	cmd := exec.Command(exe, "-wrap.batch-import")
	cmd.Env = append(os.Environ(),
		"WRAP_REGISTRY="+registry,
		"WRAP_INPUT="+manifest,
		"WRAP_FAULT="+string(fault),
		"WRAP_REASON="+reason,
		// Every batch id plus the non-ASCII products must be present in the
		// fully prepared temporary file before the replacement is refused.
		"WRAP_MARKERS="+strings.Join([]string{
			"B-OLD-1", "B-OLD-2", "B-OLD-3", "B-NEW-1", "B-NEW-2", "B-NEW-3", "苹果", "新产品😀",
		}, ","),
	)

